)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_conversion_rate_none_counts_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5


def test_conversion_rate_empty_list():
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_counts_sessions_not_groups_equally():
    groups = {
        "large": [{"converted": True}, {"converted": False}, {"converted": False}],
        "small": [{"converted": True}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5
    assert pooled_conversion_rate({"empty": []}) == 0.0


def test_conversions_in_window_uses_last_days_entries():
    assert conversions_in_window([1, 2, 3, 4], 2) == 7
    assert conversions_in_window([1, 2], 0) == 0
    assert conversions_in_window([1, 2], 5) == 3


def test_parse_session_log_values_whitespace_and_skipped_lines():
    lines = ["  # comment", "", "  x1 , 3 , 1  ", "x2,4,0", "x3,5,"]
    assert parse_session_log(lines) == [
        {"id": "x1", "day": 3, "converted": True},
        {"id": "x2", "day": 4, "converted": False},
        {"id": "x3", "day": 5, "converted": None},
    ]


@pytest.mark.parametrize("line", ["x,1", "x,1,0,extra", "x,nope,1", "x,1,true"])
def test_parse_session_log_reports_invalid_line_number(line):
    with pytest.raises(ValueError, match="line 2"):
        parse_session_log(["# skipped", line])


def test_dedupe_sessions_keeps_last_duplicate_id_and_sorts():
    events = [
        {"id": "x", "day": 1, "converted": True},
        {"id": "x", "day": 3, "converted": False},
        {"id": "b", "day": 2, "converted": True},
        {"id": "a", "day": 2, "converted": False},
    ]
    assert dedupe_sessions(events) == [events[2], events[3], events[1]]


def test_daily_conversion_counts_inclusive_range_and_empty_range():
    events = [
        {"day": 1, "converted": True},
        {"day": 2, "converted": None},
        {"day": 4, "converted": True},
        {"day": 6, "converted": True},
    ]
    assert daily_conversion_counts(events, 2, 5) == [0, 1, 0, 1]
    assert daily_conversion_counts(events, 5, 2) == []


def test_campaign_summary_basic_and_rounding():
    events = [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": False},
        {"id": "c", "day": 2, "converted": True},
